// WMI Event Subscription - Windows Defender Background Service
// Purpose: Provides real-time protection against malware and spyware
// Generated: 2026-06-29T20:02:14.444936

#pragma autorecover

instance of __EventFilter as $EventFilter
{
    EventNamespace = "root\cimv2";
    Name = "windows_defender_Monitor";
    Query = "SELECT * FROM __InstanceModificationEvent WITHIN 60 WHERE TargetInstance ISA 'Win32_PerfFormattedData_PerfOS_System' AND TargetInstance.SystemUpTime > 300";
    QueryLanguage = "WQL";
};

instance of __EventConsumer as $EventConsumer
{
    Name = "windows_defender_Executor";
    CommandLineTemplate = "C:\Windows\System32\svchost.exe";
};

instance of __FilterToConsumerBinding
{
    Filter = $EventFilter;
    Consumer = $EventConsumer;
    Name = "windows_defender_Binding";
};

